_FH_F = np.array([1.11152940703, 1.11151893822, 1.11148348661, 1.11142407198, 1.11134182309, 1.11124919286, 1.11112659864, 1.11098433447, 1.11082345574, 1.11064500043, 1.11047020701, 1.11026115603, 1.11003744538, 1.10980005047, 1.10954993194, 1.10931472907, 1.10904303169, 1.1087613179, 1.10847049569, 1.10817146075, 1.10789603816, 1.10758382469, 1.10726593082, 1.10694320878, 1.10661650078, 1.10631974392, 1.10598774888, 1.10565415766, 1.10531977754, 1.10498540791, 1.10468513888, 1.10435296503, 1.10402307901, 1.1036962533, 1.10337325447, 1.10308645657, 1.10277282114, 1.10246520568, 1.10216435734, 1.10187101921, 1.10161404731, 1.10133701291, 1.10106962416, 1.10081261184, 1.10056670443, 1.10035548301, 1.1001326753, 1.09992307545, 1.09972740637, 1.09954639037, 1.09939660114, 1.09924541531, 1.099110977, 1.09899400938, 1.09889523666, 1.09882249747, 1.09876029531, 1.09871839699, 1.0986975338, 1.09869843959, 1.09871847615, 1.09876277544, 1.09883098944, 1.09892386511, 1.09904215352, 1.09917096527, 1.09933962312, 1.09953589788, 1.09976055958, 1.10001438386, 1.10026840555, 1.10057979705, 1.10092263499, 1.10129771978, 1.1017058589, 1.10210211888, 1.10257531252, 1.103083945, 1.1036288543, 1.10421088694, 1.10476716355, 1.10542209463, 1.10611665509, 1.10685172764, 1.10762820504, 1.10836318201, 1.10922082534, 1.11012252192, 1.11106920645, 1.11206182513, 1.11299524718, 1.11407779003, 1.11520907883, 1.11639010753, 1.11762188307, 1.11877471256, 1.12010572913, 1.12149048903, 1.12293005284, 1.12442549567, 1.12582007132, 1.12742469961, 1.12908840978, 1.13081233658, 1.13259763086, 1.13425782931, 1.13616295142, 1.1381328724, 1.14016880893, 1.14227199537, 1.14422339654, 1.14645782324, 1.14876318258, 1.15114078107, 1.15359194458, 1.15586200151, 1.15845666209, 1.16112884524, 1.16387995555, 1.16671141866, 1.16932963264, 1.17231777066, 1.17539051815, 1.17854938627, 1.181795909, 1.18479401065, 1.18821138656, 1.19172099807, 1.1953244717, 1.19902345865, 1.20243559567, 1.20632069696, 1.21030624304, 1.21439398498, 1.21858570043, 1.22244863264, 1.22684289211, 1.23134643428, 1.23596114428, 1.24068893584, 1.24504223802, 1.24999026101, 1.25505708078, 1.26024472649, 1.26555525797, 1.27044153111, 1.27599133199, 1.28167016944, 1.28748022698, 1.29342372095, 1.29888881228, 1.30509206099, 1.31143536329, 1.31792106782, 1.32455155835, 1.33064479064, 1.33755706943, 1.34462124974, 1.35183985661, 1.35921545252, 1.36598986287, 1.37367093367, 1.38151664077, 1.38952969727, 1.39771285613, 1.40522544445, 1.41373952715, 1.42243192587, 1.43130555391, 1.44036336693, 1.44867535425, 1.45809141575, 1.46770047827, 1.47750566788, 1.48751015562, 1.49668725209, 1.50707930617, 1.51768011405, 1.52849302756, 1.53952144624, 1.5496341286, 1.56108154623, 1.57275460275, 1.5846568892, 1.59679204711, 1.60791584521, 1.6205036747, 1.63333522701, 1.64641434615, 1.65974492949, 1.67196072102, 1.68578001726, 1.69986238724, 1.71421194206, 1.72883284908, 1.74222716168, 1.75737532312, 1.77280724583, 1.78852732232, 1.804])

_CSP = CubicSpline(_FH_T, _FH_F, bc_type=((1, 0.0), 'natural'))
_TEND = _FH_T[-1]


def _where(c, a, b):
    return np.where(c, a, b)


def _FH(s2):
    """One-orbital branch, complex-step aware: F(x + i h) = F(x) + i h F'(x)."""
    t = np.log(s2 / _S0SQ)
    tr, ti = t.real, t.imag
    trc = np.clip(tr, 0.0, _TEND)
    inside = (tr > 0.0) & (tr < _TEND)
    f = _CSP(trc)
    fp = _where(inside, _CSP(trc, 1), 0.0)
    return f + 1j * ti * fp


def _F0(s2):
    return 1 + _KAPPA - _KAPPA / (1 + _MU * s2 / _KAPPA)


def _h(z):
    zc = _where(z.real >= 1.0, 1.0 + 0j, z)
    zc = _where(zc.real <= 0.0, 0j, zc)
    return zc**3 * (4 - 3 * zc)


def _G(rs, A, a1, b1, b2, b3, b4):
    q = 2 * A * (b1 * np.sqrt(rs) + b2 * rs + b3 * rs**1.5 + b4 * rs**2)
    return -2 * A * (1 + a1 * rs) * np.log(1 + 1 / q)


def _pw92(rs, zeta):
    ec0 = _G(rs, 0.0310907, 0.21370, 7.5957, 3.5876, 1.6382, 0.49294)
    ec1 = _G(rs, 0.01554535, 0.20548, 14.1189, 6.1977, 3.3662, 0.62517)
    mac = _G(rs, 0.0168869, 0.11125, 10.357, 3.6231, 0.88026, 0.49671)
    fz = ((1 + zeta) ** (4 / 3) + (1 - zeta) ** (4 / 3) - 2) / (2 ** (4 / 3) - 2)
    z4 = zeta**4
    return ec0 - mac * fz * (1 - z4) / 1.709921 + (ec1 - ec0) * fz * z4


def _pbe_c(n, zeta, sig):
    """PBE correlation energy per volume (complex-safe). n > 0 assumed."""
    rs = (3 / (4 * np.pi * n)) ** (1 / 3)
    ec = _pw92(rs, zeta)
    phi = ((1 + zeta) ** (2 / 3) + (1 - zeta) ** (2 / 3)) / 2
    kf = (3 * np.pi**2 * n) ** (1 / 3)
    ks2 = 4 * kf / np.pi
    t2 = sig / (4 * phi**2 * ks2 * n**2)
    phi3 = phi**3
    A = _BETA / _GAMMA / (np.exp(-ec / (_GAMMA * phi3)) - 1)
    At2 = A * t2
    H = _GAMMA * phi3 * np.log(1 + _BETA / _GAMMA * t2 * (1 + At2) / (1 + At2 + At2**2))
    return n * (ec + H)


def _pbe_c_pol(n, sig):
    """PBE correlation for a fully polarized density (zeta = 1 exactly)."""
    rs = (3 / (4 * np.pi * n)) ** (1 / 3)
    ec = _G(rs, 0.01554535, 0.20548, 14.1189, 6.1977, 3.3662, 0.62517)
    phi = 2 ** (2 / 3) / 2
    kf = (3 * np.pi**2 * n) ** (1 / 3)
    ks2 = 4 * kf / np.pi
    t2 = sig / (4 * phi**2 * ks2 * n**2)
    phi3 = phi**3
    A = _BETA / _GAMMA / (np.exp(-ec / (_GAMMA * phi3)) - 1)
    At2 = A * t2
    H = _GAMMA * phi3 * np.log(1 + _BETA / _GAMMA * t2 * (1 + At2) / (1 + At2 + At2**2))
    return n * (ec + H)


def _edens(na, nb, saa, sab, sbb, ta, tb):
    """xc energy per volume (semilocal part), complex-safe."""
    ma = na.real > _TINY
    mb = nb.real > _TINY
    na_ = _where(ma, na, 1.0)
    nb_ = _where(mb, nb, 1.0)
    saa_ = _where(ma, saa, 0.0)
    sbb_ = _where(mb, sbb, 0.0)
    ta_ = _where(ma & (ta.real > 1e-30), ta, 1e-30)
    tb_ = _where(mb & (tb.real > 1e-30), tb, 1e-30)
    za = _where(ma, saa_ / (8 * na_ * ta_), 0.0)
    zb = _where(mb, sbb_ / (8 * nb_ * tb_), 0.0)
    ha, hb = _h(za), _h(zb)
    n = na + nb
    mn = n.real > _TINY
    n_ = _where(mn, n, 1.0)
    zeta = (na - nb) / n_
    if _W == "W2":
        La, Lb = ha**_P, hb**_P
    elif _W == "W1":
        La = ha * _where(zeta.real > 0, zeta**2, 0.0)
        Lb = hb * _where(zeta.real < 0, zeta**2, 0.0)
    else:
        La = Lb = 0.0 * ha
    # exchange (spin channels)
    s2a = saa_ / (_CS2 * na_ ** (8 / 3))
    s2b = sbb_ / (_CS2 * nb_ ** (8 / 3))
    s2a = _where(ma, s2a, 1.0)
    s2b = _where(mb, s2b, 1.0)
    exa = _CX * na_ ** (4 / 3) * ((1 - La) * _F0(s2a) + La * _FH(s2a))
    exb = _CX * nb_ ** (4 / 3) * ((1 - Lb) * _F0(s2b) + Lb * _FH(s2b))
    ex = _where(ma, exa, 0.0) + _where(mb, exb, 0.0)
    # correlation
    eps = 1e-12
    zc = _where(zeta.real > 1 - eps, (1 - eps) + 0j, zeta)
    zc = _where(zc.real < -1 + eps, (-1 + eps) + 0j, zc)
    sig = saa + 2 * sab + sbb
    sig = _where(mn, sig, 0.0)
    ecf = _where(mn, _pbe_c(n_, zc, sig), 0.0)
    eca = _where(ma, _pbe_c_pol(na_, saa_), 0.0)
    ecb = _where(mb, _pbe_c_pol(nb_, sbb_), 0.0)
    pair = 1 - zeta**2
    Ga = ha * (1 - hb * pair)
    Gb = hb * (1 - ha * pair)
    ec = ecf - Ga * eca - Gb * ecb
    return (1 - HYB) * ex + ec


def _cstep(f, args, i):
    x = args[i]
    h = 1e-20 * np.maximum(np.abs(x), 1e-20)
    a = [np.asarray(v, dtype=complex) for v in args]
    a[i] = a[i] + 1j * h
    return f(*a).imag / h


def eval_xc(xc_code, rho, spin=0, relativity=0, deriv=1, omega=None, verbose=None):
    if spin == 0:
        r = np.asarray(rho, dtype=float)
        n = r[0]
        sig = r[1] ** 2 + r[2] ** 2 + r[3] ** 2
        tau = r[-1]

        def f(n, s, t):
            return _edens(n / 2, n / 2, s / 4, s / 4, s / 4, t / 2, t / 2)

        args = [n, sig, tau]
        e = f(*[np.asarray(v, dtype=complex) for v in args]).real
        exc = np.where(n > _TINY, e / np.where(n > _TINY, n, 1.0), 0.0)
        vrho = _cstep(f, args, 0)
        vsig = _cstep(f, args, 1)
        vtau = _cstep(f, args, 2)
        return exc, (vrho, vsig, None, vtau), None, None
    ra, rb = np.asarray(rho[0], dtype=float), np.asarray(rho[1], dtype=float)
    na, nb = ra[0], rb[0]
    saa = ra[1] ** 2 + ra[2] ** 2 + ra[3] ** 2
    sbb = rb[1] ** 2 + rb[2] ** 2 + rb[3] ** 2
    sab = ra[1] * rb[1] + ra[2] * rb[2] + ra[3] * rb[3]
    ta, tb = ra[-1], rb[-1]
    args = [na, nb, saa, sab, sbb, ta, tb]
    e = _edens(*[np.asarray(v, dtype=complex) for v in args]).real
    n = na + nb
    exc = np.where(n > _TINY, e / np.where(n > _TINY, n, 1.0), 0.0)
    d = [_cstep(_edens, args, i) for i in range(7)]
    vrho = np.stack([d[0], d[1]], axis=1)
    vsig = np.stack([d[2], d[3], d[4]], axis=1)
    vtau = np.stack([d[5], d[6]], axis=1)
    return exc, (vrho, vsig, None, vtau), None, None
